-- Qualifiers next to every CTA: particular, sem convênio, recibo, adults only, guardian for under-18s. Each UPDATE only touches a
-- value that still equals the previous default, so an edit made in place is never overwritten.
UPDATE pages SET title = CASE WHEN title = $q$Psicoterapia individual$q$ THEN $q$Psicoterapia individual online$q$ ELSE title END, subtitle = CASE WHEN subtitle = $q$Um espaço para entender o que mantém o seu sofrimento e construir, com apoio e método, outras formas de lidar com ele.$q$ THEN $q$Para adultos que querem entender o que mantém o próprio sofrimento e construir outras formas de lidar com ele. Em português, no Brasil ou no exterior.$q$ ELSE subtitle END, meta_title = CASE WHEN meta_title = $q$Psicoterapia individual online e na Vila Madalena, SP | João Fernandes$q$ THEN $q$Psicoterapia online para adultos | João Fernandes, CRP 06/157908$q$ ELSE meta_title END, meta_description = CASE WHEN meta_description = $q$Psicoterapia individual online ou presencial na Vila Madalena, São Paulo, com João Vitor Fernandes, psicólogo em Análise do Comportamento. CRP 06/157908.$q$ THEN $q$Psicoterapia individual online em Análise do Comportamento, para adultos no Brasil e no exterior. Sessões de cerca de 50 minutos. Particular, sem convênio, com recibo para reembolso.$q$ ELSE meta_description END WHERE slug = 'psicoterapia';
UPDATE pages SET meta_title = CASE WHEN meta_title = $q$Psicologia LGBTQIA+: Benefícios e Espaço de Acolhimento$q$ THEN $q$Psicólogo LGBTQIA+ online e em São Paulo | João Fernandes, CRP 06/157908$q$ ELSE meta_title END, meta_description = CASE WHEN meta_description = $q$O atendimento psicoterapêutico focado na população LGBTQIA+ une escuta qualificada e embasamento clínico para tratar os impactos da pressão externa.$q$ THEN $q$Psicoterapia afirmativa para pessoas LGBTQIA+, online ou na Vila Madalena, com João Vitor Fernandes, psicólogo. Atendimento particular, sem convênio, com recibo para reembolso. CRP 06/157908.$q$ ELSE meta_description END WHERE slug = 'lgbtqia';
UPDATE services SET card_description = CASE WHEN card_description = $q$Se a rotina parece caótica ou o rendimento caiu, podemos desenvolver estratégias práticas e personalizadas para melhorar seu foco e gestão de tempo, respeitando seu ritmo.$q$ THEN $q$Se a rotina parece caótica ou o rendimento caiu, podemos desenvolver estratégias práticas para foco e gestão de tempo, respeitando seu ritmo.$q$ ELSE card_description END WHERE page_id = (SELECT id FROM pages WHERE slug = 'foco-organizacao');
UPDATE services SET card_description = CASE WHEN card_description = $q$Problemas com parceiros ou família são comuns, mas desgastantes. Vamos trabalhar para melhorar a comunicação, estabelecer limites saudáveis e entender a dinâmica dessas relações.$q$ THEN $q$Problemas com parceiros ou família são comuns, mas desgastantes. Vamos trabalhar a comunicação, os limites e a dinâmica dessas relações.$q$ ELSE card_description END WHERE page_id = (SELECT id FROM pages WHERE slug = 'terapia-de-casal');
UPDATE services SET name = CASE WHEN name = $q$Autoconhecimento e avaliação psicológica$q$ THEN $q$Autoconhecimento$q$ ELSE name END, card_description = CASE WHEN card_description = $q$Muitas vezes, não sabemos explicar o que sentimos. A avaliação psicológica ajuda a dar nome e sentido para suas angústias, sendo o primeiro passo para a mudança.$q$ THEN $q$Muitas vezes, não sabemos explicar o que sentimos. A terapia ajuda a dar nome ao que se sente, mesmo sem uma questão específica.$q$ ELSE card_description END WHERE page_id = (SELECT id FROM pages WHERE slug = 'autoconhecimento');
UPDATE pages SET subtitle = CASE WHEN subtitle = $q$Testes padronizados, laudo e devolutiva para adultos e crianças, com psicólogo pós-graduado em Neuropsicologia pelo Hospital Israelita Albert Einstein$q$ THEN $q$Testes padronizados, laudo e devolutiva para adultos, adolescentes e crianças, com psicólogo pós-graduado em Neuropsicologia pelo Hospital Israelita Albert Einstein$q$ ELSE subtitle END WHERE slug = 'avaliacao-neuropsicologica';
UPDATE services SET card_description = CASE WHEN card_description = $q$Para adultos e crianças, somente presencial. Processo com entrevista, testes padronizados, laudo e sessão de devolutiva, que investiga atenção, memória, linguagem e funções executivas.$q$ THEN $q$Com pedido médico, somente presencial. Para adultos e crianças (menores de 18 anos com um responsável). Entrevista, testes padronizados, laudo e sessão de devolutiva, que investiga atenção, memória, linguagem e funções executivas.$q$ ELSE card_description END, cta_text = CASE WHEN cta_text = $q$Agendar avaliação pelo WhatsApp$q$ THEN $q$Agendar avaliação com pedido médico$q$ ELSE cta_text END WHERE page_id = (SELECT id FROM pages WHERE slug = 'avaliacao-neuropsicologica');

UPDATE faq_questions SET answer = regexp_replace(answer::text, '"url": "/plantao"', '"url": "/glossario/plantao-psicologico"')::jsonb WHERE slug = 'o-que-fazer-em-uma-crise-emocional';
